// Admin authentication: one credential, no role, no expiry.
//
// ADMIN_API_TOKEN is generated by Render and rotated monthly by
// rotate-admin-token.mjs with a verified rollback. The old ADMIN_API_TOKENS
// extension (named tokens, viewer role, expiry) was removed on 2026-11-17:
// a second admin credential that nothing rotates is a permanent backdoor.
import crypto from 'node:crypto';

const safeEqual = (a, b) => {
  if (!a || !b || a.length !== b.length) return false;
  try {
    return crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));
  } catch { return false; }
};

// One token in, zero or one entry out. Keeping the entry shape lets the audit
// log keep writing req.admin = { name, role } without a second representation.
export function adminEntries(primary = '') {
  const token = String(primary || '').trim();
  return token ? [{ name: 'admin', token, role: 'admin' }] : [];
}

export function matchAdminToken(supplied, entries) {
  if (!supplied) return null;
  for (const entry of entries) {
    if (safeEqual(supplied, entry.token)) return entry;
  }
  return null;
}
